package com.openggf.game.soniccd.objects;
import com.openggf.game.soniccd.level.*;import com.openggf.game.soniccd.player.CdPlayerMath;
import java.nio.ByteBuffer;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.objects.CdR4SolidMover.*;
/** Constructed controls for shared native bodies; no authentic World/route claim. */
class TestCdR4HMoveBlockLive {
 @Test void allNineSubtypeInitsReuseTheSameBodyAndExactNativeChildStores(){for(int subtype=0;subtype<9;subtype++){var h=new H();h.set(0x28,1,subtype);var pure=CdR4HMoveBlock.run(h.pure());assertTrue(pure.stopped().isEmpty(),"subtype "+subtype);h.run();assertEquals(pure.prefix().pool().slots(),h.place.capture().pool().slots());assertEquals(pure.prefix().primary(),h.primary);assertEquals(pure.prefix().globals(),h.globals);assertEquals(Tail.DRAW_H_WINDOW,h.tail);assertEquals(1,h.tailCalls);}}
 @Test void genuineMainSineUsesCurrentAngleAndExpiresItsReceiptAfterReturn(){var h=new H();h.set(0x24,1,2);h.set(0x28,1,1);h.set(0x3a,1,0x7F);h.run();assertEquals(1,h.sineCalls);assertEquals(0x80,CdR4SolidMover.u8(h.place.pool().state(40),0x3a));assertThrows(IllegalStateException.class,()->h.sineCall.angle());}
 @Test void sineFailureRetainsEarlierInitChildrenWithoutSolidOrTail(){var h=new H();h.set(0x28,1,1);h.sineFault=new Fault("actual sine");assertSame(h.sineFault,assertThrows(Fault.class,h::run));assertEquals(2,h.place.pool().state(40).routine());assertTrue(h.place.pool().capture().slots().stream().filter(v->v.id()==0x24).count()>1);assertEquals(0,h.solidCalls);assertEquals(0,h.tailCalls);assertEquals(0,h.sineFault.getSuppressed().length);}
 @Test void wrongDispatchIdIsRejectedBeforeAnyCallbackOrWrite(){var h=new H();h.set(0,1,0x34);var before=h.place.capture();assertThrows(IllegalArgumentException.class,h::run);assertEquals(0,h.beforeCalls);assertEquals(before.pool().slots(),h.place.capture().pool().slots());}
 @Test void foreignOffThreadAndRetiredSineCallsCannotAuthorizeReads(){var h=new H();var foreign=new H();h.set(0x24,1,2);h.set(0x28,1,1);h.onSine=()->{assertThrows(IllegalStateException.class,()->h.sineCall.requireCurrent(foreign));var failure=new AtomicReference<Throwable>();var t=new Thread(()->{try{h.sineCall.angle();}catch(Throwable e){failure.set(e);}});t.start();try{t.join();}catch(InterruptedException e){throw new AssertionError(e);}assertInstanceOf(IllegalStateException.class,failure.get());};h.run();assertThrows(IllegalStateException.class,()->h.sineCall.angle());}
 @Test void mappingRefusalKeepsOnlyActualEarlierInitStores(){var h=new H();h.data.mapFault=Mapping.H1;assertThrows(IllegalStateException.class,h::run);assertEquals(2,h.place.pool().state(40).routine());assertEquals(3,CdR4SolidMover.u8(h.place.pool().state(40),0x18));assertEquals(0,CdR4SolidMover.i32(h.place.pool().state(40),4));assertEquals(0,h.sineCalls);assertEquals(0,h.tailCalls);}
 @Test void refusedAndLandedStoresPreserveExactOriginalThrowableAndPrefixes(){var h=new H();var old=h.place.capture();h.beforeStoreFault=new Fault("refused");assertSame(h.beforeStoreFault,assertThrows(Fault.class,h::run));assertEquals(old.pool().slots(),h.place.capture().pool().slots());var landed=new H();landed.afterStoreFault=new Fault("landed");assertSame(landed.afterStoreFault,assertThrows(Fault.class,landed::run));assertEquals(2,landed.place.pool().state(40).routine());assertEquals(1,landed.stores);assertEquals(0,landed.sineCalls);}
 @Test void refusedChildXStoreMustRetainTheEarlierNativeYHeaderAndOriginalThrowable(){
  var h=new H();h.set(0x28,1,2);h.place.pool().write(put(put(h.place.pool().state(32),8,2,0xCAFE),12,2,0xBEEF));var fault=new Fault("before child X");
  h.onBefore=()->{if(h.saved instanceof ChildStoreCall call&&call.offset()==8&&call.bytes()==2)throw fault;};
  assertSame(fault,assertThrows(Fault.class,h::run));var child=h.place.pool().state(32);assertEquals(0x200,u16(child,12),"Native192 Y precedes refused195 X");assertEquals(0xCAFE,u16(child,8));assertEquals(0x24,child.id());assertEquals(2,u8(child,0x28));assertEquals(1,u8(child,0x3c));assertEquals(0x100,u16(child,0x36));assertEquals(0,h.solidCalls);assertEquals(0,h.tailCalls);assertEquals(0,fault.getSuppressed().length);
 }
 @Test void refusedParentXReadAfterSearchMustKeepTheEarlierNativeChildHeaderAndY(){
  var h=new H();h.set(0x28,1,2);h.place.pool().write(put(put(h.place.pool().state(32),8,2,0xCAFE),12,2,0xBEEF));var fault=new Fault("before parent X after allocator");
  h.onRead=()->{if(h.saved instanceof ReadCall call&&call.offset()==8&&h.calls.stream().anyMatch(SearchCall.class::isInstance))throw fault;};
  assertSame(fault,assertThrows(Fault.class,h::run));var child=h.place.pool().state(32);assertEquals(0x24,child.id(),"Native188 ID precedes193 parent X read");assertEquals(2,u8(child,0x28));assertEquals(1,u8(child,0x3c));assertEquals(0x100,u16(child,0x36));assertEquals(0x200,u16(child,12));assertEquals(0xCAFE,u16(child,8));assertEquals(0,h.solidCalls);assertEquals(0,h.tailCalls);assertEquals(0,fault.getSuppressed().length);
 }
 static final class Fault extends RuntimeException{Fault(String s){super(s);}}
 static final class H implements LiveOwner {
  final CdObjectPlacementRuntime place=placement();final TestCdR4SolidMovers.Data data=new TestCdR4SolidMovers.Data();final CdSolidObject kernel=TestCdR4SolidMovers.solid();
  CdSolidObject.Player primary=TestCdR4SolidMovers.player(0,0x1001234,0x1005678,0,0,0,0);final CdSolidObject.Gates gates=new CdSolidObject.Gates(0,0);CdSolidObject.Globals globals=new CdSolidObject.Globals(0,0,0x12,0x34);
  final List<Call> calls=new ArrayList<>();final List<String> storeFields=new ArrayList<>();long generation=7;Call saved;int beforeCalls,stores,solidCalls,tailCalls,refusedAfter,sineCalls;Tail tail;boolean running;
  Throwable nativeFirst;Fault sineFault;SineCall sineCall;Runnable onSine=()->{};Fault beforeStoreFault,afterStoreFault,afterAnyFault,solidFault,solidLandedFault,tailFault;Runnable onRead=()->{},onBefore=()->{};
  H(){set(0,1,0x24);set(8,4,0x100BEEF);set(12,4,0x200ABCD);}
  void set(int at,int size,int value){place.pool().write(CdR4SolidMover.put(place.pool().state(40),at,size,value));}
  PrimaryInputs inputs(){return new PrimaryInputs(place,40,primary,gates,globals,kernel,data);}
  Inputs pure(){return new Inputs(place.pool().capture(),40,primary,TestCdR4SolidMovers.player(2,0x2222345,0x3333456,-13,17,2,0),gates,globals,kernel,data,a->new CdPlayerMath.SineCosine(0,256),new Terrain(){public Probe floor(int x,int y){return new Probe(16,OptionalInt.empty(),OptionalInt.empty());}public Probe wall(boolean right,int x,int y){return new Probe(-1,OptionalInt.empty(),OptionalInt.empty());}},place.capture().savedFlags(),1,new Water(0x780,0x780,0x780,0x1234),new ActorWidths(16,24));}
  void run(){if(running)throw new IllegalStateException("Actual fixture owner reentry");running=true;try{CdR4HMoveBlock.run(inputs(),this);}finally{running=false;}}
  public long generation(){return generation;}
  public void requireCurrent(Call c){c.requireCurrent(this);assertTrue(running);assertSame(place,c.placement());assertEquals(40,c.wholeIndex());}
  public void before(Operation c){requireCurrent(c);saved=c;calls.add(c);beforeCalls++;onBefore.run();if(c instanceof ReadCall)onRead.run();if(c instanceof StoreCall&&beforeStoreFault!=null)throw beforeStoreFault;}
  public void after(Operation c){requireCurrent(c);if(c instanceof StoreCall store){if(c.completed()){stores++;storeFields.add(store.offset()+"/"+store.bytes());assertEquals(store.output(),place.pool().state(40));if(afterStoreFault!=null)throw afterStoreFault;}else refusedAfter++;}if(afterAnyFault!=null&&c instanceof StoreCall)throw afterAnyFault;}
  public void solid(SolidCall c){requireCurrent(c);solidCalls++;assertEquals(CdSolidObject.Entry.SOLID_OBJECT,c.entry());assertEquals(primary,c.primary());assertEquals(globals,c.globals());if(solidFault!=null)throw solidFault;var out=c.outcome();if(out instanceof CdSolidObject.Completed ok){var r=ok.completedResult();place.pool().write(r.object());for(var o:r.otherSlots())place.pool().write(o);primary=r.player();globals=r.globals();}else{nativeFirst=((CdSolidObject.NativeStopped)out).stop().originalException();var p=((CdSolidObject.NativeStopped)out).prefix();place.pool().write(p.object());for(var o:p.otherSlots())place.pool().write(o);primary=p.player();globals=p.globals();}if(solidLandedFault!=null)throw solidLandedFault;}
  public CdPlayerMath.SineCosine sine(SineCall c){requireCurrent(c);sineCalls++;sineCall=c;onSine.run();if(sineFault!=null)throw sineFault;return new CdPlayerMath.SineCosine(0,256);}
  public void tail(TailCall c){requireCurrent(c);tailCalls++;tail=c.tail();assertEquals(Tail.DRAW_H_WINDOW,tail);if(tailFault!=null)throw tailFault;}
  private static CdObjectPlacementRuntime placement(){var b=ByteBuffer.allocate(26);b.putShort((short)12).putShort((short)20).putShort((short)0xFFFF).putInt(0).putShort((short)0);b.putShort((short)0xFFFF).putInt(0).putShort((short)0);b.putShort((short)0xFFFF).putInt(0);return new CdObjectPlacementRuntime(CdObjectPlacements.decodeLayout(b.array()));}
 }
}
